10	// escKey renders key as a JSON member name in which every rune is spelled via
11	// a lowercase unicode escape (with UTF-16 surrogate pairs above the BMP),
12	// e.g. escKey("action") is the nine JSON bytes backslash-u-0-0-6-1... that
13	// decode back to "action". Building escaped names at runtime keeps the test
14	// source independent of how inline escape text is transported.
15	func escKey(key string) string {
16		var b strings.Builder
17		b.WriteByte('"')
18		for _, r := range key {
19			for _, u := range utf16.Encode([]rune{r}) {
20				fmt.Fprintf(&b, "\\u%04x", u)
21			}
22		}
23		b.WriteByte('"')
24		return b.String()
