27	// Regression coverage for the duplicate top-level field rule. Duplicates are
28	// judged by the JSON-decoded member name: a key written with a unicode escape
29	// is the same member as the literal spelling, so their coexistence fails the
30	// whole line even when both values are equal. The check runs before field
31	// validation and therefore must never degrade into a value-conflict error or
32	// let the later value win.
33	func TestNormalizeDuplicateKeysAfterJSONUnescaping(t *testing.T) {
34		withRequired := func(members string) string {
35			return `{"timestamp":"2026-01-02T00:00:00Z","action":"a",` + members + `}`
36		}
37		cases := []struct {
38			name  string
39			input string
40			field string // decoded member name the error must identify
41			diff  bool   // the repeated members carry different values
42		}{
43			{
44				name:  "canonical name escaped then literal, equal values",
45				input: withRequired(escKey("action") + `:"a","action":"a"`),
46				field: FieldAction,
47			},
48			{
49				name:  "canonical name literal then escaped, different values",
50				input: withRequired(`"action":"a",` + escKey("action") + `:"b"`),
51				field: FieldAction,
52				diff:  true,
53			},
54			{
55				name: "escaped timestamp duplicates literal timestamp",
56				input: `{` + escKey("timestamp") + `:"2026-01-02T00:00:00Z",` +
57					`"timestamp":"2026-01-02T00:00:00Z","action":"a"}`,
58				field: FieldTimestamp,
59			},
60			{
61				name:  "alias name literal and escaped",
62				input: withRequired(`"time":"2026-01-02T00:00:00Z",` + escKey("time") + `:"2026-01-02T00:00:00Z"`),
63				field: "time",
64			},
65			{
66				name:  "unknown field escaped and literal, equal values",
67				input: withRequired(escKey("foo") + `:1,"foo":1`),
68				field: "foo",
69			},
70			{
71				name:  "unknown field literal and escaped, different values",
72				input: withRequired(`"foo":1,` + escKey("foo") + `:2`),
