79				field: FieldAction,
80			},
81			{
82				name:  "Chinese member name versus its unicode escape",
83				input: withRequired(escKey("事件") + `:1,"事件":2`),
84				field: "事件",
85				diff:  true,
86			},
87		}
88		for _, tc := range cases {
89			t.Run(tc.name, func(t *testing.T) {
90				results := runNormalize(t, tc.input)
91				if len(results) != 1 || results[0]["ok"] != false {
92					t.Fatalf("decoded-same-name members must fail the whole line: %s -> %#v", tc.input, results)
93				}
94				if _, exists := results[0]["event"]; exists {
95					t.Fatalf("duplicate-field failure must not carry an event: %s -> %#v", tc.input, results[0])
96				}
97				msg, _ := results[0]["error"].(string)
98				if !strings.Contains(strings.ToLower(msg), "duplicate") {
99					t.Fatalf("error must report a duplicate field, got %q (input %s)", msg, tc.input)
100				}
101				if !strings.Contains(msg, tc.field) {
102					t.Fatalf("error must identify the decoded field name %q, got %q", tc.field, msg)
103				}
104				if tc.diff && strings.Contains(strings.ToLower(msg), "conflict") {
105					t.Fatalf("a decoded duplicate must not be reported as a value conflict: %q", msg)
106				}
107			})
108		}
109	}
